// Automatic Traffic Light System using Arduino UNO
const int RED_LED = 12;
const int YELLOW_LED = 11;
const int GREEN_LED = 10;

void setup() {
  pinMode(RED_LED, OUTPUT);
  pinMode(YELLOW_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
}

void loop() {
  // Red Light - Stop (10 Seconds)
  digitalWrite(RED_LED, HIGH);
  digitalWrite(YELLOW_LED, LOW);
  digitalWrite(GREEN_LED, LOW);
  delay(10000);

  // Green Light - Go (10 Seconds)
  digitalWrite(RED_LED, LOW);
  digitalWrite(GREEN_LED, HIGH);
  delay(10000);

  // Yellow Light - Prepare (3 Seconds)
  digitalWrite(GREEN_LED, LOW);
  digitalWrite(YELLOW_LED, HIGH);
  delay(3000);
}

// Edge-AI Current Leakage Calculation
float evaluateGridLeakage(float i_phase, float i_neutral) {
  float leakage = fabs(i_phase - i_neutral);
  if (leakage > LEAKAGE_LIMIT_MA) {
    triggerGridRelayTrip();
    publishFaultAlert(leakage);
  }
  return leakage;
}

// IoT Smart Elder Care System - Fall Detection Core
void checkElderSafety() {
  sensors_event_t a, g, temp;
  mpu.getEvent(&a, &g, &temp);
  float mag = sqrt(a.acceleration.x * a.acceleration.x + a.acceleration.y * a.acceleration.y + a.acceleration.z * a.acceleration.z) / 9.81;
  if (mag > FALL_THRESHOLD) {
    triggerEmergencyAlert("CRITICAL: Sudden Fall Detected!", mag);
  }
  publishIoTTelemetry(mag, dht.readTemperature(), dht.readHumidity());
}

